require __DIR__.'/includes/config.php';if(empty($_SESSION['user'])){header('Location:/login.php');exit;}
$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT p.*,c.cuenta,c.domicilio,u.nombre,f.folio factura_folio,f.periodo FROM pagos p JOIN cuentas_servicio c ON c.id=p.cuenta_id JOIN usuarios u ON u.id=c.usuario_id LEFT JOIN facturas f ON f.id=p.factura_id WHERE p.id=? AND c.usuario_id=?');$q->execute([$id,$_SESSION['user']['id']]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Comprobante no disponible.');}$pageTitle='Comprobante '.$p['referencia'];include __DIR__.'/includes/header.php';?>
